WITH all_returns AS (SELECT sr.sr_cdemo_sk AS demo_sk, sr.sr_net_loss AS net_loss FROM store_returns sr UNION ALL SELECT wr.wr_refunded_cdemo_sk AS demo_sk, wr.wr_net_loss AS net_loss FROM web_returns wr UNION ALL SELECT wr.wr_returning_cdemo_sk AS demo_sk, wr.wr_net_loss AS net_loss FROM web_returns wr) SELECT gender, marital_status, education_status, return_cnt, avg_net_loss, total_net_loss, DENSE_RANK() OVER (ORDER BY avg_net_loss DESC) AS loss_rank, CASE WHEN avg_net_loss > 10000 THEN 'HIGH_RISK' WHEN avg_net_loss BETWEEN 5000 AND 10000 THEN 'MEDIUM_RISK' ELSE 'LOW_RISK' END AS risk_category FROM (SELECT cd.cd_gender AS gender, cd.cd_marital_status AS marital_status, cd.cd_education_status AS education_status, COUNT(*) AS return_cnt, AVG(ar.net_loss) AS avg_net_loss, SUM(ar.net_loss) AS total_net_loss FROM all_returns ar JOIN customer_demographics cd ON ar.demo_sk = cd.cd_demo_sk GROUP BY cd.cd_gender, cd.cd_marital_status, cd.cd_education_status HAVING COUNT(*) >= 10) t ORDER BY avg_net_loss DESC LIMIT 20
